WITH unpacked AS (SELECT id, latency_ms, context, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, COALESCE(context['region'], 'direct') AS region_or_default FROM app_logs) SELECT id, latency_ms, has_region, ROW_NUMBER() OVER (ORDER BY latency_ms, id) AS row_seq, LAG(latency_ms, 1) OVER (ORDER BY latency_ms, id) AS prev_latency_ms, LEAD(latency_ms, 1) OVER (ORDER BY latency_ms, id) AS next_latency_ms, LAG(latency_ms, 1) OVER (ORDER BY latency_ms, id) AS prev_latency_ms_2, ROW_NUMBER() OVER (ORDER BY latency_ms DESC, id) AS row_seq_2 FROM unpacked
